  /* ---------- 判断推理今日题型 ---------- */
  const LOGIC_TYPES = [
    { type: '图形推理·位置规律', icon: '📐',
      formula: '位置规律：平移（方向+步数）\n旋转：旋转角度、方向（顺时针/逆时针）\n翻转：左右翻转、上下翻转',
      example: '区分旋转180°、左右翻转、上下翻转三种变化的本质区别？',
      solution: '旋转180°：图形上下左右均变化；左右翻转：左右变化但上下不变；上下翻转：上下变化但左右不变。抓住图形中"不对称特征"的朝向变化即可判断。',
      freq: '必考（近5年每年均考1-2题）', 'years': '2017—2021年连续考查', 'key': '福建省考位置规律是必考考点，平移、旋转、翻转均涉及。解题先看元素是否"只改变位置"：若图形间元素相同只是位置变，优先考虑位置规律。平移要数准"步数+方向"，旋转/翻转重点用不对称特征（如L形、箭头）判断方向变化。', 'pitfall': '①旋转与翻转混淆是最大陷阱，务必用不对称特征（如角、开口方向）判断，而不是整体是否"看起来像"；②平移题注意是"循环移动"还是"往返移动"，到达边界后是回起点还是折返；③多个元素同时移动时，分别观察每个元素的位置变化。' },
    { type: '图形推理·数量规律', icon: '🔢',
      formula: '数量规律：点、线、面、素（元素个数）\n数面：封闭区域个数\n数素：元素种类数、元素个数',
      example: '一组图形中封闭区域个数分别为1、2、3、4，下一幅图应有多少个封闭区域？',
      solution: '数面规律：封闭区域数依次+1，故下一幅图应为5个封闭区域。福建省考对面和素的数量考查最频繁。',
      freq: '高频（近5年考查6题）', 'years': '2017、2018、2019、2020年均有考查（数面/数素最多）', 'key': '福建省考数量规律以"数面（封闭区域）"和"数素（元素种类/个数）"最常考。特征：图形凌乱、无明显位置变化时优先考虑数量。数面找封闭区域，数素看元素种类是否递增/递减。', 'pitfall': '①数面时容易把"面"与"线围成的开放区域"混淆，只数封闭的空白区域；②数素要看是"数种类"还是"数个数"，题干元素种类增减与个数增减要分清；③点线面素要依次排查，不要一上来就猜，避免漏掉隐藏规律。' },
    { type: '定义判断', icon: '📖',
      formula: '单定义：抓住核心关键词，选项逐项比对\n多定义：先定位题干所问的定义再作答',
      example: '根据"正当防卫"的定义，判断"丙被人抢劫，反抗中将劫匪推倒致其轻伤"是否属于正当防卫？',
      solution: '属于。丙"反抗正在进行的不法侵害（抢劫）"，采取制止行为致轻伤，符合正当防卫要件。核心是抓住"正在进行的不法侵害"这一关键信息。',
      freq: '每年必考（单定义为主，多定义每年1-3题）', 'years': '2017—2021年每年均有考查', 'key': '福建定义判断题干较长、难度大。三步走：①看清提问（"属于/不属于""符合/不符合"，多定义问的是哪个）；②抓关键词——主客体（个人/组织/企业/政府）、方式目的（根据/通过/利用）、原因结果（由于/导致）、限制条件（当…时）；③对比择优，选项纠结时选最符合的。', 'pitfall': '①主客体错位是最常见的错误——选项的主语或对象与定义不符，直接排除；②"属于"与"不属于""符合"与"不符合"看错，导致反向选择；③只看到部分关键词就下结论，遗漏其他要件。' },
    { type: '类比推理·对应语义', icon: '🔗',
      formula: '对应关系：功能、材料、配套、属性、人物地点、职业等\n语义关系：近义、反义、比喻象征义\n种属vs组成：用"……是……"造句判断',
      example: '"玫瑰：花"是什么关系？与"老虎：猫科动物"是否一致？',
      solution: '种属关系——"玫瑰是花的一种""老虎是猫科动物的一种"。用"……是……"造句能通的就是种属关系，不能通（如"笔画：汉字"）则是组成关系。',
      freq: '必考（对应关系每年必考，语义关系每年1-4题）', 'years': '2017—2021年连续考查（常考成语语义）', 'key': '类比推理"看似简单实则难"。①对应关系是"筐"，功能、材料、配套、职业等都要有常识积累；②语义关系常考成语——"指鹿为马：颠倒黑白"近义、"少小离家：老大回乡"反义；③分清种属（……是……）与组成（不是……是……的一部分）。', 'pitfall': '①"种属"与"组成"分不清是最高频错误，牢记用"……是……"造句验证；②近义/反义成语积累不足，遇到生僻成语先排除确定不符合的再择优；③并列关系要区分"矛盾关系"（非此即彼）与"反对关系"（有第三种情况）。' },
    { type: '逻辑判断·加强论证', icon: '💪',
      formula: '加强方式：补充论据、搭桥（建立联系）、必要条件、举例加强\n论证结构：论据 →（论证）→ 论点',
      example: '研究表明每天步行1万步者患心血管病风险更低，据此认为"步行越多越健康"。以下哪项最能加强？',
      solution: '能补充"步行能改善心肺功能、降低血压"等支持性论据，即加强因果。解题三步：①找准论点和论据；②预设可能的加强方式；③与选项对比择优。',
      freq: '逻辑判断占比最大（加强+削弱每年7-9题）', 'years': '2017—2021年每年必考', 'key': '加强论证与削弱论证是逻辑判断的重点，占比最大。核心：①看清提问（加强还是削弱、能否加强）；②找准"靶子"——论点、论据；③预设可能的答案形式再与选项对比；④警惕无关选项、不直接明确的选项。', 'pitfall': '①"无关选项"最常设陷阱——选项内容与论点无关，不能加强；②加强程度有强弱：搭桥＞必要条件＞补充论据＞举例，择优时比较力度；③看清是"最能加强"还是"不能加强"，反向设问易失分。' },
    { type: '逻辑判断·削弱论证', icon: '🛡️',
      formula: '削弱方式：否定论点、拆桥（切断联系）、否定论据、另有他因、因果倒置',
      example: '研究表明每天步行1万步者患心血管病风险更低，据此认为"步行越多越健康"。以下哪项最能削弱？',
      solution: '"样本量小，且多为年轻健康人群"指出样本偏差（另有他因/样本不具代表性），削弱了因果结论。削弱力度：否定论点＞拆桥＞否定论据＞另有他因。',
      freq: '逻辑判断占比最大（加强+削弱每年7-9题）', 'years': '2017—2021年每年必考', 'key': '削弱论证是福建逻辑判断的考查重心。常见削弱方式：否定论点、拆桥（切断论据与论点联系）、另有他因、因果倒置。先找论点和论据，判断削弱方式，再比较选项削弱力度强弱。', 'pitfall': '①"另有他因"与"因果倒置"易混淆——因果倒置是"结果反当原因"，削弱力度更强；②只削弱论据的力度小于直接否定论点；③选项若加强了论点或与题干无关，不能选。' },
    { type: '逻辑判断·翻译推理', icon: '🧠',
      formula: '前推后："如果…就…""只要…就…""所有…都…" → A→B\n后推前："只有…才…""不…不…""除非…否则不…" → B→A\n规则：肯前必肯后，否后必否前；否前肯后不确定',
      example: '"只有加强研发投入，企业才能在竞争中胜出。"翻译为逻辑形式，并判断"某企业加强了研发投入"能推出什么？',
      solution: '"只有A，才B"即A（加强研发）是B（胜出）的必要条件，翻译为"胜出→加强研发"。已知加强研发（肯后），不能推出胜出。关键是熟记"肯前必肯后，否后必否前，否前肯后不确定"。',
      freq: '高频（福建省考较为重要考点）', 'years': '2017—2021年多次考查', 'key': '翻译推理考法固定，靠背规则就能"送分"。①记住翻译形式：前推后（如果…就/只要…就/所有…都）、后推前（只有…才/不…不/除非…否则不）；②熟记"肯前必肯后、否后必否前、否前肯后不确定"；③掌握"且"（同时成立）与"或"（至少一个）的推理规则。', 'pitfall': '①翻译方向搞反是最常见错误——"只有…才…"是后推前，不是前推后；②"否前"或"肯后"就下结论，违反了推理规则（不确定）；③"或"关系的否定（非A且非B）易出错，须熟记德摩根定律。' },
    { type: '逻辑判断·分析推理', icon: '🧩',
      formula: '组合排列：代入法、排除法、列表法\n真假话：找矛盾关系，一真一假\n从确定信息入手逐步推导',
      example: '甲、乙、丙三人中只有一人是医生。甲说"我不是医生"，乙说"丙是医生"，丙说"乙是医生"。已知只有一人说真话，则医生是？',
      solution: '用假设法/代入法：若甲是医生，则甲假、乙假、丙假，符合"只有一人真话"；若乙是医生，则甲真、丙真，不符。故甲是医生。抓住"只有一人真话"找矛盾关系或用假设法验证。',
      freq: '一般考点（组合排列2019年考过，真假话/分析推理穿插考查）', 'years': '2019年考查组合排列，真假话等分析推理历年穿插出现', 'key': '分析推理（组合排列、真假话）要用巧劲：①组合排列优先用"确定信息"入手，配合代入法、排除法、列表法；②真假话题找"矛盾关系"（两个必一真一假），其余为假或为真再推导；③题干条件多时，列表整理信息比空想更清晰。', 'pitfall': '①真假话"找矛盾"要准确——只有互为矛盾的两句才一真一假，其余不能保证；②组合排列直接硬推容易超时，优先用排除法（选项信息充分时）；③代入法验证要严格，所有条件都满足才能选。' }
  ];

